#!/usr/bin/env python3
"""Build every generated file of this extension from the pinned facts.

Inputs: tests/reference/allegro_api.json (extract_reference.py), names.py (titles and
areas), step_ids.json (frozen step ids) and composite_specs.py (the everyday steps).
Outputs: runtime/registry.json, the four contract files, ui/actions/actions.yaml,
the Allegro API and Coverage pages, and extension.yaml. Run from the bundle root:

    python3 tests/reference/build_contracts.py

tests/test_contracts.py fails when a committed file differs from what this script
renders, so the files never drift from the specification.

A step id is written once to step_ids.json (``--new-ids`` adds ids for operations
that have none) and never derived again: titles may change, ids may not.
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path
from typing import Any

import yaml

