# -- names ---------------------------------------------------------------------------------


def snake(text: str) -> str:
    text = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", text)
    text = re.sub(r"[^A-Za-z0-9]+", "_", text)
    return text.strip("_").lower()


def input_name(param: str) -> str:
    return snake(param)


def key(op: dict[str, Any]) -> str:
    return f"{op['method']} {op['path']}"


def facts() -> dict[str, Any]:
    return json.loads(FACTS.read_text(encoding="utf-8"))


def step_ids() -> dict[str, str]:
    return json.loads(STEP_IDS.read_text(encoding="utf-8")) if STEP_IDS.exists() else {}


def new_step_id(title: str) -> str:
    words = [
        w
        for w in snake(title.replace("'s", "").replace("e-mail", "email")).split("_")
        if w not in {"a", "an", "the"}
    ]
    return "_".join(words)


# -- parameters ----------------------------------------------------------------------------


def node(schema: dict[str, Any], *, required: bool) -> dict[str, Any]:
    """How one parameter value is checked and sent (see runtime/params.py)."""
    kind = schema.get("type") or "string"
    out: dict[str, Any] = {"required": required}
    if kind == "integer":
        out["kind"] = "integer"
        for bound in ("minimum", "maximum"):
            if bound in schema:
                out[bound] = int(schema[bound])
    elif kind == "number":
        out["kind"] = "decimal"
        for bound in ("minimum", "maximum"):
            if bound in schema:
                out[bound] = str(schema[bound])
    elif kind == "boolean":
        out["kind"] = "boolean"
    elif kind == "array":
        items = schema.get("items") or {}
        out["kind"] = "text_list"
        out["max_items"] = int(schema.get("maxItems") or 1000)
        if items.get("enum"):
            out["allowed"] = [str(v) for v in items["enum"]]
        out["item_max_length"] = int(items.get("maxLength") or 1000)
    elif kind == "object":
        out["kind"] = "pairs"
    else:
        out["kind"] = "text"
        out["max_length"] = int(schema.get("maxLength") or 2000)
        if schema.get("minLength"):
            out["min_length"] = int(schema["minLength"])
        if schema.get("enum"):
            out["allowed"] = [str(v) for v in schema["enum"]]
    return out


def clean_media(media: str) -> str:
    """The spec writes one media type with a stray space ("…v1 +json"); sent without it."""
    return media.replace(" ", "")


def choose_json(types: list[str]) -> str | None:
    for wanted in JSON_TYPES:
        if wanted in types:
            return wanted
    return None


def success_types(op: dict[str, Any]) -> list[str]:
    seen: list[str] = []
    for code, resp in op["responses"].items():
        if code[:1] in {"2", "3"}:
            for media in resp["content"]:
                media = clean_media(media)
                if media not in seen:
                    seen.append(media)
    return seen


def formats_of(op: dict[str, Any]) -> dict[str, str]:
    """{format name: media type} of an operation whose successful answers are documented
    both as JSON and in another type, with no Accept parameter to choose between them;
    empty otherwise. JSON stays the default."""
    if any(p["in"] == "header" and p["name"].lower() == "accept" for p in op["parameters"]):
        return {}
    types = success_types(op)
    json_type = choose_json(types)
    other = [t for t in types if t not in JSON_TYPES]
    if not json_type or not other:
        return {}
    out = {"json": json_type}
    for media in other:
        if media not in FORMAT_NAMES:
            raise SystemExit(f"{key(op)}: no format name for {media}")
        out[FORMAT_NAMES[media]] = media
    return out


def answer_of(op: dict[str, Any]) -> tuple[str, str | None, list[str]]:
    """(answer kind, Accept header, the Accept choices of a step that asks for one)."""
    choices: list[str] = []
    for prm in op["parameters"]:
        if prm["in"] == "header" and prm["name"].lower() == "accept" and prm["schema"].get("enum"):
            choices = [str(v) for v in prm["schema"]["enum"]]
    if choices:
        return "file", None, choices
    types = success_types(op)
    json_type = choose_json(types)
    if json_type:
        return "json", json_type, []
    binary = [t for t in types if t not in JSON_TYPES]
    if binary:
        return "file", ", ".join(binary), []
    return "json", PUBLIC, []


def documented_refusals(op: dict[str, Any]) -> dict[str, bool]:
    """4xx statuses the operation documents: {status: its body must be an Allegro error}.

    A refusal proves that nothing changed only when its status is documented and, when
    the documentation gives the status a body, that body has the documented error form.
    """
    out: dict[str, bool] = {}
    for code, resp in op["responses"].items():
        if code.isdigit() and 400 <= int(code) < 500:
            out[code] = bool(resp["content"])
    return out


def request_of(op: dict[str, Any]) -> dict[str, Any] | None:
    request = op["request"]
    if not request:
        return None
    content = request["content"]
    out: dict[str, Any] = {
        "required": request["required"],
        "json": None,
        "binary": [],
        "multipart": None,
    }
    json_media = choose_json(list(content))
    if json_media:
        shape = content[json_media]
        out["json"] = {
            "content_type": json_media,
            "type": shape.get("type") or "object",
            "required": shape.get("required") or [],
            "properties": shape.get("properties") or [],
            "closed": bool(shape.get("closed")) and not shape.get("variants"),
        }
    for media, shape in content.items():
        if media == "multipart/form-data":
            out["multipart"] = shape["parts"]
        elif media not in JSON_TYPES and (shape.get("binary") or shape.get("type") == "string"):
            out["binary"].append(media)
    return out


def area_of(op: dict[str, Any]) -> str:
    tag = op["tags"][0]
    for area, tags in names.AREAS.items():
        if tag in tags:
            return area
    raise SystemExit(f"tag {tag!r} has no area")


_READ_MORE = re.compile(
    r"\s*(Read more|For more information|More information)[^.]*?(PL\s*/\s*EN|EN\s*/\s*PL)\.?",
    re.IGNORECASE,
)


def clean(text: str) -> str:
    """Vendor text without leftover markdown (bullets, escapes, bold)."""
    text = _READ_MORE.sub("", text)
    text = re.sub(r"\s*\(?\s*PL\s*/\s*EN\s*\)?\.?", "", text)
    text = text.replace("\\-", "-").replace("**", "")
    text = re.sub(r"(^|\s)\*\s+-?\s*", " ", text)
    text = " ".join(text.split())
    text = re.sub(r"\s+([.,;:])", r"\1", text)
    text = re.sub(r"\.(\s*\.)+", ".", text)
    # The UI pages never use the word "limits" (a reviewed rule); Allegro's own
    # sentences say "rate limited" and "limit", so only the plural is reworded.
    text = re.sub(r"\blimits\b", "maximums", text)
    text = re.sub(r"\bLimits\b", "Maximums", text)
    return text.replace("`", "")


def sentences(text: str, limit: int) -> str:
    text = clean(text)
    out = ""
    for part in re.split(r"(?<=[.!?])\s+", text):
        if not part:
            continue
        candidate = f"{out} {part}".strip()
        if len(candidate) > limit:
            break
        out = candidate
    if not out and text:
        out = text[: limit - 1].rstrip() + "…"
    return out


def kind_of(op: dict[str, Any]) -> str:
    if op["method"] == "GET" or (op["method"], op["path"]) in READ_ONLY_NON_GET:
        return "read"
    return "write"


def processing_of(op: dict[str, Any], ids: dict[str, str]) -> dict[str, Any] | None:
    """How a write's answer is read: always accepted (a registered command), accepted on
    HTTP 202, or completed; and the step that reads the outcome of an accepted one."""
    if kind_of(op) != "write":
        return None
    where = (op["method"], op["path"])
    check: tuple[str, str] | None = None
    if where in ACCEPTED_ONLY:
        check = ACCEPTED_ONLY[where][0]
        always = True
    else:
        always = False
        check = ACCEPTED_ON_202.get(where)
        if "202" in op["responses"] and where not in ACCEPTED_ON_202:
            raise SystemExit(f"{key(op)} documents HTTP 202 but names no check step")
    return {
        "accepted_always": always,
        "check": ids[f"{check[0]} {check[1]}"] if check else None,
        "check_title": names.TITLES[check] if check else None,
    }


def describe(op: dict[str, Any], entry: dict[str, Any]) -> str:
    text = sentences(op["description"], 420) or op["summary"].rstrip(".") + "."
    if not text.endswith((".", "!", "?", "…")):
        text += "."
    notes: list[str] = []
    if op["deprecated"]:
        notes.append("Allegro marks this operation as deprecated.")
    if entry["beta"]:
        notes.append("Beta in Allegro: it may still change.")
    if entry["answer"] == "file":
        notes.append("The answer is saved as a workflow file.")
    for name in entry.get("formats") or {}:
        if name != "json":
            notes.append(f"With format {name} the answer is saved as a workflow file.")
    processing = entry.get("processing")
    if processing:
        then = (
            f" Get the outcome with {processing['check_title']}."
            if processing["check_title"]
            else " Get the outcome from Allegro afterwards."
        )
        if processing["accepted_always"]:
            notes.append(
                "Allegro registers the request and applies it afterwards: the step returns "
                'processing "accepted" and applied false.' + then
            )
        elif "202" in entry["success"]:
            notes.append(
                "When Allegro answers HTTP 202 it has accepted the request and applies it "
                'afterwards: the step returns processing "accepted" and applied false.' + then
            )
    if op["user_scopes"]:
        notes.append("Needs the Allegro permission " + " or ".join(op["user_scopes"]) + ".")
    else:
        notes.append("The specification names no Allegro permission for it.")
    return " ".join([text, *notes])


# -- the registry --------------------------------------------------------------------------


def registry_entry(op: dict[str, Any], step_id: str, ids: dict[str, str]) -> dict[str, Any]:
    answer, accept, accept_choices = answer_of(op)
    path_params: list[dict[str, Any]] = []
    query: list[dict[str, Any]] = []
    headers: list[dict[str, Any]] = []
    for prm in op["parameters"]:
        where = prm["in"]
        if where == "path":
            path_params.append(
                {
                    "name": prm["name"],
                    "input": input_name(prm["name"]),
                    "node": {
                        **node(prm["schema"], required=True),
                        "kind": "text",
                        "max_length": 500,
                    },
                }
            )
        elif where == "query":
            name = prm["name"]
            query.append(
                {
                    "name": name,
                    "input": input_name(name),
                    "node": node(prm["schema"], required=prm["required"]),
                    "description": prm["description"],
                }
            )
        elif where == "header":
            lowered = prm["name"].lower()
            if lowered in HEADER_INPUTS:
                headers.append(
                    {
                        "name": prm["name"],
                        "input": HEADER_INPUTS[lowered],
                        "node": node(prm["schema"], required=prm["required"]),
                        "description": prm["description"],
                    }
                )
            elif lowered not in {"accept", "content-type"}:
                raise SystemExit(f"{key(op)}: header {prm['name']!r} is not handled")
        else:
            raise SystemExit(f"{key(op)}: parameter in {where!r} is not handled")
    request = request_of(op)
    beta = (
        accept == BETA
        or bool(request and request["json"] and request["json"]["content_type"] == BETA)
        or "[BETA]" in op["summary"].upper()
        or "(beta)" in op["summary"].lower()
    )
    entry: dict[str, Any] = {
        "title": names.TITLES[(op["method"], op["path"])],
        "method": op["method"],
        "path": op["path"],
        "server": op["server"],
        "vendor_operation_id": op["operation_id"],
        "tag": op["tags"][0],
        "area": area_of(op),
        "kind": kind_of(op),
        "deprecated": op["deprecated"],
        "beta": beta,
        "scopes": op["user_scopes"],
        "answer": answer,
        "accept": accept,
        "accept_choices": accept_choices,
        "path_params": path_params,
        "query": query,
        "headers": headers,
        "body": request,
        "success": sorted(c for c in op["responses"] if c[:1] in {"2", "3"}),
        "refusals": documented_refusals(op),
    }
    processing = processing_of(op, ids)
    if processing:
        entry["processing"] = processing
    formats = formats_of(op)
    if formats:
        entry["formats"] = formats
        other = next(m for n, m in formats.items() if n != "json")
        entry["file"] = {
            "filename": "allegro-" + snake(step_id).replace("_", "-") + "." + FORMAT_NAMES[other],
            "content_type": other,
        }
    if answer == "file":
        media = accept_choices[0] if accept_choices else (accept or "").split(", ")[0]
        filename, content_type = DOWNLOAD_FILES.get(
            media, ("allegro-file.bin", "application/octet-stream")
        )
        if accept_choices:
            filename, content_type = "allegro-labels", "application/octet-stream"
        entry["file"] = {"filename": filename, "content_type": content_type}
    entry["description"] = describe(op, entry)
    names_used = [p["input"] for p in path_params + query + headers]
    if len(set(names_used)) != len(names_used) or set(names_used) & (
        RESERVED_INPUTS - {"accept_language"}
    ):
        raise SystemExit(f"{key(op)}: input names collide: {names_used}")
    return entry


def ordered_operations(
    data: dict[str, Any], ids: dict[str, str]
) -> list[tuple[str, dict[str, Any]]]:
    """Areas in order, then tags in order; reads first, deletions last within a tag."""
    weight = {"GET": 0, "POST": 1, "PUT": 2, "PATCH": 3, "DELETE": 4}
    area_order = list(names.AREAS)
    tag_order = [t for tags in names.AREAS.values() for t in tags]
    rows = []
    for index, op in enumerate(data["operations"]):
        rows.append(
            (
                area_order.index(area_of(op)),
                tag_order.index(op["tags"][0]),
                weight[op["method"]],
                index,
                ids[key(op)],
                op,
            )
        )
    rows.sort(key=lambda r: r[:4])
    return [(r[4], r[5]) for r in rows]


def build_registry(data: dict[str, Any], ids: dict[str, str]) -> dict[str, Any]:
    operations = {sid: registry_entry(op, sid, ids) for sid, op in ordered_operations(data, ids)}
    return {
        "source": data["source"],
        "scopes": sorted({s for op in data["operations"] for s in op["user_scopes"]}),
        "operations": operations,
    }


# -- contract rows -------------------------------------------------------------------------


def value_type(schema: dict[str, Any]) -> str:
    kind = schema.get("type")
    if isinstance(kind, list):
        kinds = [k for k in kind if k != "null"]
        if len(kinds) != 1:
            return "text"
        kind = kinds[0]
    return {"integer": "integer", "boolean": "boolean", "array": "array", "object": "object"}.get(
        str(kind), "text"
    )


def node_schema(entry: dict[str, Any], *, title: str, description: str) -> dict[str, Any]:
    n = entry
    kind = n["kind"]
    schema: dict[str, Any]
    if kind == "integer":
        schema = {"type": "integer", **{k: n[k] for k in ("minimum", "maximum") if k in n}}
    elif kind == "decimal":
        schema = {"type": ["number", "string"]}
    elif kind == "boolean":
        schema = {"type": "boolean"}
    elif kind == "text_list":
        items: dict[str, Any] = {"type": "string", "maxLength": n["item_max_length"]}
        if n.get("allowed"):
            items = {"type": "string", "enum": n["allowed"]}
        schema = {"type": "array", "items": items, "maxItems": n["max_items"]}
    elif kind == "pairs":
        schema = {"type": "object", "additionalProperties": {"type": ["string", "array"]}}
    else:
        schema = {"type": "string", "maxLength": n["max_length"]}
        if n.get("min_length"):
            schema["minLength"] = n["min_length"]
        if n.get("allowed"):
            schema["enum"] = n["allowed"]
    schema["title"] = title
    if description:
        schema["description"] = description
    return schema


def step_inputs(entry: dict[str, Any]) -> list[dict[str, Any]]:
    """Every input of a generated step: (name, required, schema, widget, help)."""
    rows: list[dict[str, Any]] = []
    for prm in entry["path_params"]:
        rows.append(
            {
                "name": prm["input"],
                "required": True,
                "schema": node_schema(
                    prm["node"], title=prm["name"], description=f"The {prm['name']} in the path."
                ),
                "widget": "text",
            }
        )
    for prm in entry["query"] + entry["headers"]:
        n = prm["node"]
        description = clean(prm["description"]) or prm["name"]
        rows.append(
            {
                "name": prm["input"],
                "required": bool(n["required"]),
                "schema": node_schema(n, title=prm["name"], description=description[:400]),
                "widget": widget_for(n),
                "options": n.get("allowed"),
            }
        )
    if entry["accept_choices"]:
        rows.append(
            {
                "name": "accept",
                "required": True,
                "schema": {
                    "type": "string",
                    "enum": entry["accept_choices"],
                    "title": "Format",
                    "description": "The file format Allegro returns.",
                },
                "widget": "select",
                "options": entry["accept_choices"],
            }
        )
    formats = entry.get("formats")
    if formats:
        names_ = list(formats)
        others = [n for n in names_ if n != "json"]
        ignored = [
            prm["input"]
            for prm in entry["query"]
            if re.search(
                r"ignored for (" + "|".join(map(re.escape, formats.values())) + ")",
                prm["description"],
                re.IGNORECASE,
            )
        ]
        note = ""
        if ignored:
            note = (
                " "
                + ", ".join(ignored)
                + " do not apply with "
                + " or ".join(others)
                + " (Allegro ignores them for that format)."
            )
        rows.append(
            {
                "name": "format",
                "required": False,
                "schema": {
                    "type": "string",
                    "enum": names_,
                    "title": "Format",
                    "description": (
                        "json (default): Allegro's answer in data. "
                        + ", ".join(others)
                        + ": the answer as a workflow file in file."
                        + note
                    ),
                },
                "widget": "select",
                "options": names_,
            }
        )
    body = entry["body"]
    if body:
        alone = not body["json"] or not (body["binary"] or body["multipart"])
        if body["json"]:
            shape = body["json"]
            needed = ", ".join(shape["required"]) or "none"
            rows.append(
                {
                    "name": "body",
                    "required": body["required"] and alone,
                    "schema": {
                        "type": "array" if shape["type"] == "array" else "object",
                        **({"additionalProperties": True} if shape["type"] != "array" else {}),
                        "title": "Request body",
                        "description": (
                            f"The JSON body Allegro documents for {entry['vendor_operation_id']} "
                            f'(required fields: {needed}). Amounts as text, for example "49.99".'
                        ),
                    },
                    "widget": "json",
                }
            )
        if body["binary"] or body["multipart"]:
            what = (
                "PDF" if body["multipart"] else "/".join(m.split("/")[-1] for m in body["binary"])
            )
            rows.append(
                {
                    "name": "file",
                    "required": body["required"] and alone,
                    "schema": {
                        "title": "File",
                        "description": f"The file to upload ({what}), up to 16 MB.",
                    },
                    "widget": "artifact_picker",
                    "value_type": "artifact_handle",
                }
            )
        if body["binary"]:
            rows.append(
                {
                    "name": "content_type",
                    "required": False,
                    "schema": {
                        "type": "string",
                        "enum": body["binary"],
                        "title": "File type",
                        "description": "The file's type. Default: " + body["binary"][0] + ".",
                    },
                    "widget": "select",
                    "options": body["binary"],
                }
            )
        for part in body["multipart"] or []:
            if part["encoding"] != "binary":
                rows.append(
                    {
                        "name": snake(part["name"]),
                        "required": part["required"],
                        "schema": {
                            "type": "string",
                            "maxLength": 200,
                            "title": part["name"],
                            "description": part["description"] or part["name"],
                        },
                        "widget": "text",
                    }
                )
    return rows


def widget_for(n: dict[str, Any]) -> str:
    kind = n["kind"]
    if kind == "integer":
        return "integer"
    if kind == "boolean":
        return "boolean"
    if kind == "text_list":
        return "multi_select" if n.get("allowed") else "json"
    if kind == "pairs":
        return "key_value"
    if n.get("allowed"):
        return "select"
    return "text"


def generic_outputs(entry: dict[str, Any]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = [
        {
            "name": "status",
            "type": ["integer", "null"],
            "description": "Allegro's HTTP status (none in a test run).",
        }
    ]
    if entry["answer"] == "file":
        rows += [
            {
                "name": "file",
                "type": ["string", "null"],
                "value_type": "artifact_handle",
                "description": "Allegro's answer, as a workflow file (none when Allegro sent no content).",
            },
            {
                "name": "content_type",
                "type": ["string", "null"],
                "description": "The file's type as Allegro sent it.",
            },
            {"name": "size_bytes", "type": ["integer", "null"], "description": "The file's size."},
        ]
    else:
        rows.append(
            {
                "name": "data",
                "type": ["object", "array", "string", "number", "boolean", "null"],
                "description": "What Allegro returned (JSON).",
            }
        )
        if entry.get("formats"):
            rows += [
                {
                    "name": "file",
                    "type": ["string", "null"],
                    "value_type": "artifact_handle",
                    "description": "With a format other than json: Allegro's answer, as a workflow file.",
                },
                {
                    "name": "content_type",
                    "type": ["string", "null"],
                    "description": "The file's type as Allegro sent it.",
                },
                {
                    "name": "size_bytes",
                    "type": ["integer", "null"],
                    "description": "The file's size.",
                },
            ]
    if entry["kind"] == "write":
        rows += PROCESSING_OUTPUTS
    rows += [
        {
            "name": "location",
            "type": ["string", "null"],
            "description": "The Location header, when Allegro sends one (for an accepted request: where Allegro reports its outcome).",
        },
        {
            "name": "etag",
            "type": ["string", "null"],
            "description": "The ETag header, when Allegro sends one (the version for if_match).",
        },
        WARNINGS_OUTPUT,
    ]
    if entry["kind"] == "write":
        rows += [
            {"name": "external_effect_status", "type": "string"},
            {"name": "definitely_no_external_effect", "type": "boolean"},
        ]
    return rows


def output_row(row: dict[str, Any]) -> dict[str, Any]:
    schema = {k: v for k, v in row.items() if k not in {"name", "value_type"}}
    vt = row.get("value_type") or value_type(schema)
    if row["name"] == "data":
        vt = "object"
        schema["additionalProperties"] = True
    return {"name": row["name"], "value_type": vt, "schema": schema}


def composite_input_rows(spec: dict[str, Any]) -> list[dict[str, Any]]:
    rows = []
    for item in spec["inputs"]:
        schema = {k: v for k, v in item.items() if k not in {"name"}}
        required = bool(item.get("minItems")) or item["name"] in {"batch_key"}
        widget = "text"
        if item["type"] == "integer":
            widget = "integer"
        elif item["type"] == "array":
            widget = "multi_select" if item["items"].get("enum") else "json"
        elif item.get("enum"):
            widget = "select"
        rows.append(
            {
                "name": item["name"],
                "required": required,
                "schema": schema,
                "widget": widget,
                "options": item.get("enum") or item.get("items", {}).get("enum"),
            }
        )
    return rows


def manifest_rows(registry: dict[str, Any]) -> list[dict[str, Any]]:
    """One row per step in step order: id, title, description, kind, inputs, outputs."""
    rows: list[dict[str, Any]] = []
    for spec in composite_specs.COMPOSITES:
        rows.append(
            {
                "id": spec["operation_id"],
                "title": spec["title"],
                "description": spec["description"],
                "kind": spec["kind"],
                "inputs": composite_input_rows(spec),
                "outputs": spec["outputs"],
                "area": "Everyday",
                "calls": spec["calls"],
                "file": COMPOSITE_FILES.get(spec["operation_id"]),
            }
        )
    for sid, entry in registry["operations"].items():
        rows.append(
            {
                "id": sid,
                "title": entry["title"],
                "description": entry["description"],
                "kind": entry["kind"],
                "inputs": step_inputs(entry),
                "outputs": generic_outputs(entry),
                "area": entry["area"],
                "calls": [f"{entry['method']} {entry['path']}"],
                "file": entry.get("file"),
                "body": entry["body"],
            }
        )
    return rows


def operation_manifest(rows: list[dict[str, Any]]) -> dict[str, Any]:
    ops = []
    for row in rows:
        write = row["kind"] == "write"
        inputs = [{"name": "connection_ref", "value_type": "connection_ref", "required": True}]
        for item in row["inputs"]:
            vt = item.get("value_type") or value_type(item["schema"])
            inputs.append(
                {
                    "name": item["name"],
                    "value_type": vt,
                    "required": item["required"],
                    "schema": item["schema"],
                }
            )
        op: dict[str, Any] = {
            "operation_id": row["id"],
            "display_name": row["title"],
            "description": row["description"],
            "operation_kind": "action" if write else "source",
            "category": "sales",
            "connection_type_ids": list(CONNECTION_TYPES),
            "workflow_visible": True,
        }
        if write:
            op["effect_kind"] = f"allegro_{row['id']}"
        outputs = [output_row(o) for o in row["outputs"]]
        op.update(
            {
                "inputs": inputs,
                "outputs": outputs,
                "result_fields": [f"result.{o['name']}" for o in outputs],
                "error_codes": ERROR_CODES_WRITE if write else ERROR_CODES_READ,
            }
        )
        ops.append(op)
    return {"operations": ops}


def step_ui_manifest(rows: list[dict[str, Any]]) -> dict[str, Any]:
    forms = []
    for row in rows:
        fields = []
        for item in row["inputs"]:
            field: dict[str, Any] = {
                "name": item["name"],
                "label": item["schema"].get("title") or item["name"],
                "widget_type": item["widget"],
                "required": item["required"],
                "help_text": (item["schema"].get("description") or item["name"])[:400],
            }
            if item.get("options"):
                field["options"] = [{"label": v, "value": v} for v in item["options"]]
            if item["widget"] == "json":
                field["placeholder"] = "[]" if item["schema"].get("type") == "array" else "{}"
            fields.append(field)
        forms.append({"operation_id": row["id"], "title": row["title"], "fields": fields})
    return {"forms": forms}


def actions_manifest(rows: list[dict[str, Any]]) -> dict[str, Any]:
    actions = []
    for row in rows:
        write = row["kind"] == "write"
        action: dict[str, Any] = {
            "action_id": row["id"],
            "title": row["title"],
            "description": row["description"],
            "required_scopes": ["extension:invoke"],
            "handler": {"mode": "extension"},
        }
        if write:
            action["command_type"] = "invoke_extension_action"
        action.update(
            {
                "mutates_platform": write,
                "workflow_visible": True,
                "parameters": [
                    {"name": "connection_ref", "type": "connection_ref", "required": True}
                ]
                + [
                    {
                        "name": i["name"],
                        "type": "artifact_handle"
                        if i.get("value_type") == "artifact_handle"
                        else value_type(i["schema"])
                        if value_type(i["schema"]) != "text"
                        else "string",
                        "required": i["required"],
                    }
                    for i in row["inputs"]
                ],
                "result_fields": [o["name"] for o in row["outputs"]],
                "error_codes": ERROR_CODES_WRITE if write else ERROR_CODES_READ,
            }
        )
        actions.append(action)
    verify = composite_specs.VERIFY_IDENTITY
    actions.append(
        {
            "action_id": verify["action_id"],
            "title": verify["title"],
            "description": verify["description"],
            "required_scopes": ["extension:invoke"],
            "handler": {"mode": "extension"},
            "mutates_platform": False,
            "workflow_visible": False,
            "parameters": [],
        }
    )
    return {"actions": actions}


def artifact_policies(rows: list[dict[str, Any]]) -> dict[str, Any]:
    policies = []
    for row in rows:
        entry: dict[str, Any] = {"operation_id": row["id"]}
        body = row.get("body")
        if body and (body["binary"] or body["multipart"]):
            entry["inputs"] = [
                {
                    "kind": "artifact",
                    "value_type": "artifact_handle",
                    "binding_key": UPLOAD_BINDING,
                    "field": "file",
                    "required": False,
                    "max_size_bytes": MAX_UPLOAD_BYTES,
                }
            ]
        if row.get("file"):
            entry["outputs"] = [
                {
                    "kind": "artifact",
                    "value_type": "artifact_handle",
                    "binding_key": DOWNLOAD_BINDING,
                    "filename": row["file"]["filename"],
                    "content_type": row["file"]["content_type"],
                    "max_size_bytes": MAX_DOWNLOAD_BYTES,
                    "retention_class": "run_window",
                }
            ]
        if len(entry) > 1:
            policies.append(entry)
    return {"artifact_policies": policies}


def connection_types(registry: dict[str, Any]) -> dict[str, Any]:
    scopes = registry["scopes"]
    required = ["allegro:api:profile:read"]
    optional = [s for s in scopes if s not in required]
    rows = []
    for type_id, environment in CONNECTION_TYPES.items():
        sandbox = environment == "sandbox"
        rows.append(
            {
                "connection_type_id": type_id,
                "display_name": "Allegro Sandbox" if sandbox else "Allegro",
                "description": (
                    "An Allegro Sandbox test account (allegro.pl.allegrosandbox.pl), authorized "
                    "with your Allegro Sandbox application."
                    if sandbox
                    else "An Allegro seller account (allegro.pl), authorized with your Allegro application."
                ),
                "auth": {
                    "type": "oauth2",
                    "provider_id": type_id,
                    "scopes": {"required": required, "optional": optional},
                },
                "capabilities": {"test_connection": True},
            }
        )
    return {"connection_types": rows}


