PAGE_IDS = {
    "Offers": "allegro-api-offers",
    "Products and categories": "allegro-api-products",
    "Pricing and promotion": "allegro-api-pricing",
    "Orders and returns": "allegro-api-orders",
    "Delivery and shipping": "allegro-api-delivery",
    "Account and fulfillment": "allegro-api-account",
}


def step_text(row: dict[str, Any]) -> str:
    kind = "changes data in Allegro" if row["kind"] == "write" else "reads only"
    calls = ", ".join(f"`{c}`" for c in row["calls"])
    inputs = [f"`{i['name']}`" + (" (required)" if i["required"] else "") for i in row["inputs"]]
    lines = [
        f"### {row['title']}",
        "",
        row["description"],
        "",
        f"Action id `{row['id']}` · {kind} · Allegro: {calls}",
        "",
        "Inputs: " + (", ".join(inputs) if inputs else "none") + ".",
        "",
    ]
    if row["area"] == "Everyday":
        outputs = ", ".join(
            f"`{o['name']}`"
            for o in row["outputs"]
            if o["name"] not in {"external_effect_status", "definitely_no_external_effect"}
        )
        lines += ["Results: " + outputs + ".", ""]
    return "\n".join(lines)


def api_pages(rows: list[dict[str, Any]], registry: dict[str, Any]) -> dict[str, dict[str, Any]]:
    pages: dict[str, dict[str, Any]] = {}
    total = len(rows)
    counts = {area: sum(1 for r in rows if r["area"] == area) for area in PAGE_IDS}
    overview = "\n".join(
        [
            f"The steps call the Allegro REST API for the connected account. Every documented "
            f"operation has a step: {total} steps in all, the everyday ones first.",
            "",
            "- **Permissions.** Each step names the Allegro permission it needs. Your Allegro "
            "application must have it, or Allegro refuses the step and nothing changes.",
            "- **Results.** A generated step returns `status`, `data` (Allegro's JSON) or `file` "
            "(a workflow file for PDFs, labels and attachments), `location`, `etag` and `warnings`.",
            "- **Request bodies** are given as JSON in `body`, exactly as Allegro documents them; "
            'amounts as text such as "49.99".',
            "- **Accepted or completed.** Every step that changes data returns `processing`: "
            "`completed` when Allegro answered that the change is made, `accepted` when Allegro "
            "registered a command or accepted the request (HTTP 202) and applies it afterwards. "
            "With `accepted`, `applied` is false and `check` names the step that reads the "
            "outcome and the address Allegro returned for it.",
            "- **Changes are sent once.** A step that changes data is never retried automatically; "
            "when its outcome is unclear it says so, and you check Allegro before running it again. "
            "Test runs never send changes.",
            "- **Rate limit.** When Allegro answers that a limit is reached (HTTP 429) the step "
            "stops, says how long Allegro asks to wait, and nothing is changed.",
            "",
            "The steps by area:",
            "",
            *[f"- **{area}** ({counts[area]} steps)" for area in PAGE_IDS],
        ]
    )
    everyday = "\n".join(step_text(r) for r in rows if r["area"] == "Everyday")
    pages["ui/pages/allegro-api.yaml"] = {
        "page_id": "allegro-api",
        "title": "Allegro API",
        "description": "How the Allegro steps work, and the everyday steps.",
        "components": [
            {
                "component_id": "api_overview",
                "type": "markdown",
                "title": "How the steps work",
                "body": overview + "\n",
            },
            {
                "component_id": "steps_everyday",
                "type": "markdown",
                "title": "Everyday",
                "body": everyday,
            },
        ],
    }
    for area, page_id in PAGE_IDS.items():
        area_rows = [r for r in rows if r["area"] == area]
        components = []
        for tag in names.AREAS[area]:
            tag_rows = [r for r in area_rows if registry["operations"][r["id"]]["tag"] == tag]
            if not tag_rows:
                continue
            components.append(
                {
                    "component_id": "steps_" + snake(tag),
                    "type": "markdown",
                    "title": tag[:1].upper() + tag[1:],
                    "body": "\n".join(step_text(r) for r in tag_rows),
                }
            )
        pages[f"ui/pages/{page_id}.yaml"] = {
            "page_id": page_id,
            "title": f"Allegro API: {area}",
            "description": f"The {len(area_rows)} {area.lower()} steps.",
            "components": components,
        }
    return pages


def coverage_page(registry: dict[str, Any]) -> dict[str, Any]:
    ops = registry["operations"].values()
    source = registry["source"]
    by_method: dict[str, int] = {}
    for e in ops:
        by_method[e["method"]] = by_method.get(e["method"], 0) + 1
    files = sum(1 for e in ops if e["answer"] == "file" or e.get("formats"))
    uploads = sum(1 for e in ops if e["body"] and (e["body"]["binary"] or e["body"]["multipart"]))
    beta = sum(1 for e in ops if e["beta"])
    deprecated = sum(1 for e in ops if e["deprecated"])
    total = len(registry["operations"])
    gets = by_method.get("GET", 0)
    reads = sum(1 for e in ops if e["kind"] == "read")
    accepted = sum(1 for e in ops if (e.get("processing") or {}).get("accepted_always"))
    body = "\n".join(
        [
            f"The Allegro REST API specification (OpenAPI {source['openapi']}, downloaded "
            f"{source['downloaded']}, SHA-256 `{source['sha256'][:12]}…`) documents {total} "
            f"operations; **{total} of them have their own step** in this version.",
            "",
            f"- **{reads} reads**: {gets} GET and {reads - gets} POST that Allegro documents "
            "as retrieving, calculating, querying or parsing (labels, protocols, pickup "
            "proposals, fee preview, Allegro Prices query, ingredients). Test runs send reads.",
            f"- **{total - reads} changes**: {by_method.get('POST', 0) - (reads - gets)} POST, "
            f"{by_method.get('PUT', 0)} PUT, {by_method.get('PATCH', 0)} PATCH and "
            f"{by_method.get('DELETE', 0)} DELETE. Test runs never send them. {accepted} of them "
            "register a command or request that Allegro applies afterwards; they return "
            "processing accepted and name the step that reads the outcome.",
            f"- **{files} steps save a file** (PDF, labels, attachments, CSV) and **{uploads} upload one**.",
            f"- **{beta} steps are beta** and **{deprecated} deprecated** in Allegro.",
            "",
            "The everyday steps on top: test the connection, get all your offers, update stock and "
            "prices of many offers, read the outcome of that update, and get orders and order events.",
        ]
    )
    return {
        "page_id": "coverage",
        "title": "Coverage",
        "description": "What of the documented Allegro REST API the steps offer.",
        "components": [
            {
                "component_id": "coverage_summary",
                "type": "markdown",
                "title": "Coverage",
                "body": body + "\n",
            }
        ],
    }


# -- output --------------------------------------------------------------------------------


def outputs() -> dict[str, Any]:
    data = facts()
    ids = step_ids()
    missing = [key(op) for op in data["operations"] if key(op) not in ids]
    if missing:
        raise SystemExit(f"no step id for {missing[:5]}; run with --new-ids")
    registry = build_registry(data, ids)
    rows = manifest_rows(registry)
    out: dict[str, Any] = {
        "runtime/registry.json": registry,
        "contracts/operation_manifest.yaml": operation_manifest(rows),
        "contracts/step_ui_manifest.yaml": step_ui_manifest(rows),
        "contracts/artifact_policies.yaml": artifact_policies(rows),
        "contracts/connection_types.yaml": connection_types(registry),
        "ui/actions/actions.yaml": actions_manifest(rows),
        "ui/pages/coverage.yaml": coverage_page(registry),
        "extension.yaml": extension_yaml(rows, registry),
    }
    out.update(api_pages(rows, registry))
    return out


class _Dumper(yaml.SafeDumper):
    pass


def _str(dumper: yaml.SafeDumper, value: str) -> Any:
    style = "|" if "\n" in value else None
    return dumper.represent_scalar("tag:yaml.org,2002:str", value, style=style)


_Dumper.add_representer(str, _str)


def render(path: str, value: Any) -> str:
    if path.endswith(".json"):
        return json.dumps(value, ensure_ascii=False, indent=1, sort_keys=True) + "\n"
    if path == "extension.yaml":
        # The form `flow-steward extensions lock-deps` writes, so it changes nothing.
        return yaml.safe_dump(value, sort_keys=False, allow_unicode=True)
    return HEADER + yaml.dump(value, Dumper=_Dumper, sort_keys=False, allow_unicode=True, width=100)


def main(argv: list[str]) -> int:
    if "--new-ids" in argv:
        data = facts()
        ids = step_ids()
        used = (
            set(ids.values())
            | {c["operation_id"] for c in composite_specs.COMPOSITES}
            | {"verify_identity"}
        )
        for op in data["operations"]:
            if key(op) not in ids:
                sid = new_step_id(names.TITLES[(op["method"], op["path"])])
                if sid in used:
                    raise SystemExit(f"step id {sid} is taken")
                ids[key(op)] = sid
                used.add(sid)
        STEP_IDS.write_text(json.dumps(ids, indent=1, sort_keys=True) + "\n", encoding="utf-8")
    for path, value in outputs().items():
        target = BUNDLE / path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(render(path, value), encoding="utf-8")
    print("generated", len(outputs()), "files")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
